  "py": "import asyncio\nfrom dataclasses import dataclass, field\nfrom datetime import timedelta\n\nfrom temporalio import activity, workflow\n\nTASK_QUEUE = \"imports\"\nACTIVITY_OPTS = dict(start_to_close_timeout=timedelta(seconds=30))\nMAX_RECENT_ERRORS = 5  # keep query payloads small and bounded\n\n\n@dataclass\nclass ImportInput:\n    total_records: int\n    chunk_size: int = 100\n\n\n@dataclass\nclass ChunkResult:\n    ok: int\n    failed: int\n    errors: list[str] = field(default_factory=list)\n\n\n@dataclass\nclass Progress:\n    total: int\n    done: int\n    failed: int\n    percent: float\n    chunks_done: int\n    recent_errors: list[str]\n    elapsed_seconds: float\n    eta_seconds: float | None\n    finished: bool\n\n\n@activity.defn\nasync def import_chunk(start: int, size: int) -> ChunkResult:\n    # In production: read records [start, start+size) and write them to the target system.\n    await asyncio.sleep(0.15)\n    bad = [i for i in range(start, start + size) if i % 37 == 0]  # pretend every 37th record is invalid\n    return ChunkResult(ok=size - len(bad), failed=len(bad), errors=[f\"record {i}: invalid email\" for i in bad])\n\n\n@workflow.defn\nclass ImportWorkflow:\n    @workflow.init\n    def __init__(self, inp: ImportInput) -> None:\n        self.total = inp.total_records\n        self.done = 0\n        self.failed = 0\n        self.chunks_done = 0\n        self.recent_errors: list[str] = []\n        self.started_at = workflow.now()\n        self.finished = False\n\n    @workflow.query\n    def progress(self) -> Progress:\n        # O(1): everything is kept in counters, nothing is computed over big collections.\n        elapsed = (workflow.now() - self.started_at).total_seconds()\n        processed = self.done + self.failed\n        eta = None if self.finished or processed == 0 else elapsed / processed * (self.total - processed)\n        return Progress(\n            total=self.total, done=self.done, failed=self.failed,\n            percent=round(100 * processed / self.total, 1) if self.total else 100.0,\n            chunks_done=self.chunks_done, recent_errors=list(self.recent_errors),\n            elapsed_seconds=elapsed, eta_seconds=eta, finished=self.finished,\n        )\n\n    @workflow.run\n    async def run(self, inp: ImportInput) -> Progress:\n        for start in range(0, inp.total_records, inp.chunk_size):\n            size = min(inp.chunk_size, inp.total_records - start)\n            r = await workflow.execute_activity(import_chunk, args=[start, size], **ACTIVITY_OPTS)\n            self.done += r.ok\n            self.failed += r.failed\n            self.chunks_done += 1\n            self.recent_errors = (self.recent_errors + r.errors)[-MAX_RECENT_ERRORS:]\n        self.finished = True\n        return self.progress()",
  "ts": "// ===== progress.ts =====\nimport { defineQuery, proxyActivities, setHandler } from '@temporalio/workflow';\nimport type * as activities from './progress.activities';\n\nexport const TASK_QUEUE = 'imports';\nconst MAX_RECENT_ERRORS = 5; // keep query payloads small and bounded\n\nconst { importChunk } = proxyActivities<typeof activities>({ startToCloseTimeout: '30 seconds' });\n\nexport interface ImportInput {\n  totalRecords: number;\n  chunkSize?: number;\n}\nexport interface Progress {\n  total: number;\n  done: number;\n  failed: number;\n  percent: number;\n  chunksDone: number;\n  recentErrors: string[];\n  elapsedSeconds: number;\n  etaSeconds: number | null;\n  finished: boolean;\n}\n\nexport const progressQuery = defineQuery<Progress>('progress');\n\nexport async function importWorkflow(input: ImportInput): Promise<Progress> {\n  const total = input.totalRecords;\n  const chunkSize = input.chunkSize ?? 100;\n  const startedAt = Date.now();\n  let done = 0, failed = 0, chunksDone = 0, finished = false;\n  let recentErrors: string[] = [];\n\n  // O(1): everything is kept in counters, nothing is computed over big collections.\n  const progress = (): Progress => {\n    const elapsedSeconds = (Date.now() - startedAt) / 1000;\n    const processed = done + failed;\n    const etaSeconds = finished || processed === 0 ? null : (elapsedSeconds / processed) * (total - processed);\n    return {\n      total, done, failed, chunksDone, recentErrors: [...recentErrors], elapsedSeconds, etaSeconds, finished,\n      percent: total ? Math.round((1000 * processed) / total) / 10 : 100,\n    };\n  };\n  setHandler(progressQuery, progress);\n\n  for (let start = 0; start < total; start += chunkSize) {\n    const size = Math.min(chunkSize, total - start);\n    const r = await importChunk(start, size);\n    done += r.ok;\n    failed += r.failed;\n    chunksDone++;\n    recentErrors = [...recentErrors, ...r.errors].slice(-MAX_RECENT_ERRORS);\n  }\n  finished = true;\n  return progress();\n}\n\n// ===== progress.activities.ts =====\nexport interface ChunkResult {\n  ok: number;\n  failed: number;\n  errors: string[];\n}\n\nexport async function importChunk(start: number, size: number): Promise<ChunkResult> {\n  // In production: read records [start, start+size) and write them to the target system.\n  await new Promise((r) => setTimeout(r, 150));\n  const bad: number[] = [];\n  for (let i = start; i < start + size; i++) if (i % 37 === 0) bad.push(i); // pretend every 37th record is invalid\n  return { ok: size - bad.length, failed: bad.length, errors: bad.map((i) => 'record ' + i + ': invalid email') };\n}"
